+    const a = r() * Math.PI * 2, s = (0.4 + r()) * spd;
+    dust.emit(x + (r() - 0.5) * 0.2, Math.max(0.05, y), z + (r() - 0.5) * 0.2, Math.cos(a) * s, 0.6 + r() * spd * 0.6, Math.sin(a) * s, 1.2 + r() * 1.3, 0.5 + r() * 0.4, 2.2 + r() * 1.6, 0.22 + r() * 0.12);
+  }
