+    const a = r() * Math.PI * 2, s = 2 + r() * 7;
+    sparks.emit(x, Math.max(0.03, y), z, Math.cos(a) * s, 1 + r() * 4.5, Math.sin(a) * s, 0.3 + r() * 0.55, 0.05 + r() * 0.05, 0.03, 1);
