+/* ------------------------------------------------------------------ */
+/* Breaking                                                            */
+/* ------------------------------------------------------------------ */
+function detach(part) {
+  if (part.detached) return;
+  part.detached = true;
+  const b = part.body;
+  S.crashed = true;
+  b.collisionFilterGroup = G.DET;
+  b.collisionFilterMask = G.GROUND | G.BRICK | G.ATT;
+  S.delayed.push({ t: S.time + 0.12, body: b, mask: G.GROUND | G.BRICK | G.ATT | G.DET });
+  if (part.wheel) {
+    b.material = S.m.tireFree; b.angularDamping = 0.15;
+    b.angularVelocity.set(b.angularVelocity.x + b.velocity.z / part.r, b.angularVelocity.y, b.angularVelocity.z - b.velocity.x / part.r);
+  }
+  for (const j of S.joints) if (!j.broken && (j.part === part)) { world.removeConstraint(j.c); j.broken = true; }
+  emitDust(b.position.x, b.position.y, b.position.z, 5, 2.2);
+  emitSparks(b.position.x, b.position.y, b.position.z, 8);
+  S.trauma = Math.max(S.trauma, 0.45);
+  if (part.glass) shatter(part);
+}
+
+function shatter(part) {
+  if (part.shattered) return;
+  part.shattered = true;
+  const b = part.body, { hx, hz, nx, nz } = part.panel, rg = S.rng;
+  world.removeBody(b);
+  part.mesh.visible = false;
+  const n = nx * nz, cw = hx / nx, ch = hz / nz;
+  const ql = new CANNON.Quaternion();
+  for (let i = 0; i < nx; i++) for (let j = 0; j < nz; j++) {
+    const lx = -hx + (i + 0.5) * (2 * hx / nx) + (rg() - 0.5) * cw * 0.3;
+    const lz = -hz + (j + 0.5) * (2 * hz / nz) + (rg() - 0.5) * ch * 0.3;
+    const sx = cw * (0.55 + 0.4 * rg()), sz = ch * (0.55 + 0.4 * rg());
+    const wp = b.pointToWorldFrame(new CANNON.Vec3(lx, 0, lz));
+    const sb = new CANNON.Body({
+      mass: Math.max(0.05, b.mass / n), material: S.m.car, linearDamping: 0.01, angularDamping: 0.05,
+      allowSleep: true, sleepSpeedLimit: 0.25, sleepTimeLimit: 0.5
+    });
+    sb.addShape(new CANNON.Box(new CANNON.Vec3(sx, 0.006, sz)));
+    sb.position.copy(wp);
+    ql.setFromAxisAngle(UY, (rg() - 0.5) * 1.2);
+    b.quaternion.mult(ql, sb.quaternion);
+    const nrm = b.vectorToWorldFrame(UY);
+    b.getVelocityAtWorldPoint(wp, sb.velocity);
+    const pushN = (rg() - 0.5) * 2.4;
+    sb.velocity.x += (rg() - 0.5) * 3.2 + nrm.x * pushN;
+    sb.velocity.y += (rg() - 0.3) * 2.5 + 0.8 + nrm.y * pushN;
+    sb.velocity.z += (rg() - 0.5) * 3.2 + nrm.z * pushN;
+    sb.angularVelocity.set((rg() - 0.5) * 14, (rg() - 0.5) * 14, (rg() - 0.5) * 14);
+    sb.collisionFilterGroup = G.DET; sb.collisionFilterMask = G.GROUND | G.BRICK;
+    sb.fx = 'shard';
+    world.addBody(sb);
+    S.delayed.push({ t: S.time + 0.3, body: sb, mask: G.GROUND | G.BRICK | G.ATT | G.DET });
