+}
+
+function checkJoints() {
+  if (S.time < 0.4) return;
+  for (const j of S.joints) {
+    if (j.broken) continue;
+    const eq = j.c.equations;
+    let f = Math.hypot(eq[0].multiplier, eq[1].multiplier, eq[2].multiplier);
+    if (eq.length >= 6) f += 0.4 * Math.hypot(eq[3].multiplier, eq[4].multiplier, eq[5].multiplier);
+    j.part.body.pointToWorldFrame(j.c.pivotA, tv);
+    j.parent.body.pointToWorldFrame(j.c.pivotB, tv2);
+    const stretch = tv.distanceTo(tv2);
+    const dmg = Math.min(0.7, Math.max(j.part.dmg, j.parent.dmg * 0.5));
+    if (f > j.thr * (1 - dmg) || stretch > 0.12) {
+      j.broken = true; world.removeConstraint(j.c);
+      detach(j.part);
+    }
+  }
+}
+
+function processContacts() {
+  const cs = world.contacts, bud = S.budget;
+  bud.dust = 3; bud.spark = 4;
+  for (let i = 0; i < cs.length; i++) {
+    const c = cs[i], A = c.bi, B = c.bj;
+    let P, O;
+    if (A.fx === 'part') { P = A; O = B; }
+    else if (B.fx === 'part') { P = B; O = A; }
+    else {
+      if ((A.fx === 'brick' && B.fx === 'ground') || (B.fx === 'brick' && A.fx === 'ground')) {
+        if (bud.dust > 0) {
+          const v = Math.abs(c.getImpactVelocityAlongNormal());
+          if (v > 5) { bud.dust--; emitDust(A.position.x + c.ri.x, 0.05, A.position.z + c.ri.z, 1, 0.9); }
+        }
+      }
+      continue;
+    }
+    const of = O.fx;
+    if (of === 'part' || of === 'shard') continue;
+    const v = Math.abs(c.getImpactVelocityAlongNormal());
+    const px = A.position.x + c.ri.x, py = A.position.y + c.ri.y, pz = A.position.z + c.ri.z;
+    const part = P.part;
+    if (of === 'brick') {
+      if (v > 3) {
+        S.hit = true;
+        part.dmg = Math.min(0.9, part.dmg + 0.0035 * v);
+        if (part.glass && !part.detached && v > 6) detach(part);
+        if (v > 8) S.trauma = Math.max(S.trauma, Math.min(1, v / 26));
+        if (v > 8 && bud.spark > 0) { bud.spark--; emitSparks(px, py, pz, 2); }
+        if (v > 5 && bud.dust > 0) { bud.dust--; emitDust(px, py, pz, 1, 1.4); }
+      }
+    } else if (of === 'ground') {
+      if (part.glass) { if (v > 6 && !part.detached) detach(part); continue; }
+      if (v > 6 && bud.spark > 0 && !part.wheel) { bud.spark--; emitSparks(px, py, pz, 2); }
+      if (v > 7 && bud.dust > 0) { bud.dust--; emitDust(px, py, pz, 1, 1.2); }
+      const vx = P.velocity.x, vz = P.velocity.z;
+      if (!(part.wheel && !part.detached) && vx * vx + vz * vz > 6.25) {
+        const last = P._mk;
+        if (!last || (last[0] - px) * (last[0] - px) + (last[1] - pz) * (last[1] - pz) > 0.16) {
+          P._mk = [px, pz]; addMark(px, pz, vx, vz, part.wheel ? S.cfg.carW * 0.14 : 0.14);
+        }
+      }
+    } else if (of === 'static') {
+      if (v > 4) {
+        part.dmg = Math.min(0.9, part.dmg + 0.004 * v);
+        if (bud.spark > 0) { bud.spark--; emitSparks(px, py, pz, 3); }
+        S.trauma = Math.max(S.trauma, Math.min(0.8, v / 30));
+      }
+    }
+  }
+}
+
+function stepSim() {
+  const dt = S.dt, lay = S.lay;
+  const noseX = S.tub.body.position.x + 0.57 * S.cfg.carL;
+  if (!S.driveOff && (noseX >= lay.stopX || S.hit)) { S.driveOff = true; S.driveOffT = S.time; }
+  const brake = S.hit || (S.driveOff && S.time - S.driveOffT > 0.8);
+  for (const p of S.parts) {
+    if (p.shattered) continue;
+    const b = p.body;
+    if (!S.driveOff && !p.detached) b.force.x += b.mass * lay.accel;
+    if (brake && b.position.y < 0.9) { const kk = b.mass * 1.1; b.force.x -= kk * b.velocity.x; b.force.z -= kk * b.velocity.z; }
+    if (p.wheel && !p.detached) {
+      b.vectorToWorldFrame(UX, tv3);
+      p.spin -= (b.velocity.x * tv3.x + b.velocity.y * tv3.y + b.velocity.z * tv3.z) * dt / p.r;
+    }
+  }
+  world.step(dt);
+  S.time += dt;
+  checkJoints();
+  processContacts();
+  if (S.delayed.length) {
+    for (let i = S.delayed.length - 1; i >= 0; i--) {
+      const d = S.delayed[i];
+      if (S.time >= d.t) { d.body.collisionFilterMask = d.mask; S.delayed.splice(i, 1); }
+    }
+  }
+  S.settleT += dt;
+  if (S.settleT >= 0.25) {
+    S.settleT = 0;
+    if (S.hit) {
+      let mx = 0;
+      for (const p of S.parts) if (!p.shattered) mx = Math.max(mx, p.body.velocity.length());
+      for (const b of S.bricks) if (b.body.sleepState !== CANNON.Body.SLEEPING) mx = Math.max(mx, b.body.velocity.length());
+      for (const s of S.shards) if (s.body.sleepState !== CANNON.Body.SLEEPING) mx = Math.max(mx, s.body.velocity.length());
+      S.settle = mx < 0.25 ? S.settle + 0.25 : 0;
+      S.settled = S.settle >= 1.25;
+    }
+  }
+}
