+/* ------------------------------------------------------------------ */
+/* Scene sync                                                          */
+/* ------------------------------------------------------------------ */
+const _sc = new THREE.Vector3();
+function syncScene() {
+  for (const p of S.parts) {
+    if (p.shattered) continue;
+    const b = p.body;
+    p.mesh.position.set(b.position.x, b.position.y, b.position.z);
+    p.mesh.quaternion.set(b.quaternion.x, b.quaternion.y, b.quaternion.z, b.quaternion.w);
+    if (p.spinner) p.spinner.rotation.z = p.spin;
+  }
+  for (const s of S.shards) {
+    const b = s.body;
+    s.mesh.position.set(b.position.x, b.position.y, b.position.z);
+    s.mesh.quaternion.set(b.quaternion.x, b.quaternion.y, b.quaternion.z, b.quaternion.w);
+  }
+  let sumX = 0, dirty = false;
+  const bm = S.brickMesh;
+  for (let i = 0; i < S.bricks.length; i++) {
+    const br = S.bricks[i], b = br.body;
+    sumX += b.position.x;
+    const sleeping = b.sleepState === CANNON.Body.SLEEPING;
+    if (sleeping && br.synced) continue;
+    br.synced = sleeping; dirty = true;
+    _p.set(b.position.x, b.position.y, b.position.z);
+    _q.set(b.quaternion.x, b.quaternion.y, b.quaternion.z, b.quaternion.w);
+    _sc.set(br.sx, br.sy, br.sz);
+    _m4.compose(_p, _q, _sc); bm.setMatrixAt(i, _m4);
+  }
+  if (dirty) bm.instanceMatrix.needsUpdate = true;
+  S.brickMeanX = S.bricks.length ? sumX / S.bricks.length : S.lay.wallX;
+
+  const items = S.blobItems, blm = S.blobMesh;
+  for (let i = 0; i < items.length; i++) {
+    const it = items[i], b = it.body;
+    if (b.sleepState === CANNON.Body.SLEEPING && it.done) continue;
+    it.done = b.sleepState === CANNON.Body.SLEEPING;
+    const q = b.quaternion;
+    const yaw = Math.atan2(2 * (q.w * q.y + q.x * q.z), 1 - 2 * (q.y * q.y + q.z * q.z));
+    const s = clamp(1 - (b.position.y - it.base) / it.fade, 0, 1);
+    _q.setFromAxisAngle(Y_AXIS, yaw);
+    _p.set(b.position.x, 0.014, b.position.z);
+    _sc.set((2 * it.rx + 0.25) * s + 0.0001, 1, (2 * it.rz + 0.25) * s + 0.0001);
+    _m4.compose(_p, _q, _sc); blm.setMatrixAt(i, _m4);
+  }
+  blm.instanceMatrix.needsUpdate = true;
+}
