+/* ------------------------------------------------------------------ */
+/* Cameras                                                             */
+/* ------------------------------------------------------------------ */
+const camPos = new THREE.Vector3(), camLook = new THREE.Vector3();
+const dPos = new THREE.Vector3(), dLook = new THREE.Vector3();
+let snap = true;
+const controls = new OrbitControls(camera, canvas);
+controls.enableDamping = true; controls.dampingFactor = 0.08;
+controls.minDistance = 3; controls.maxDistance = 140; controls.maxPolarAngle = 1.52;
+controls.autoRotate = true; controls.autoRotateSpeed = 0.9; controls.enabled = false;
+let resumeTimer = 0;
+controls.addEventListener('start', () => { controls.autoRotate = false; clearTimeout(resumeTimer); });
+controls.addEventListener('end', () => { clearTimeout(resumeTimer); resumeTimer = setTimeout(() => { if (camMode === 'orbit') controls.autoRotate = true; }, 3500); });
+
+function impactFocus(pos, look) {
+  const t = S.tub.body.position, A = t.x, B = S.brickMeanX;
+  const span = Math.max(4.8, Math.abs(B - A) + 3.2 + Math.max(0, S.lay.wallW - 6) * 0.5);
+  const fx = (A + B) / 2;
+  look.set(fx, 0.9, 0);
+  pos.set(fx - 0.12 * span - 3.4, 2.4 + 0.14 * span, 6.2 + 0.62 * span);
+}
+
+function updateTopCam() {
+  if (!S) return;
+  const L = S.cfg.trackLen, hw = S.lay.hw;
+  const aspect = innerWidth / innerHeight;
+  const tanV = Math.tan(topCam.fov * Math.PI / 360);
+  const h = Math.max((L + 10) / (2 * tanV * aspect), (hw * 2 + 3) / (2 * tanV));
+  topCam.position.set(L / 2 + 1, h, 0);
+  topCam.lookAt(L / 2 + 1, 0, 0);
+}
+
+function updateCamera(rdt, vdt) {
+  if (camMode === 'top') return;
+  const t = S.tub.body.position;
+  if (camMode === 'impact') impactFocus(dPos, dLook);
+  else if (camMode === 'follow') {
+    const back = 6.5 + Math.max(0, S.lay.wallW - 6) * 0.5;
+    dPos.set(t.x - back, 2.4, 2.8); dLook.set(t.x + 5, 0.8, -0.2);
+  } else {
+    impactFocus(dPos, dLook);
+    if (snap) { controls.target.copy(camLook.lengthSq() ? camLook : dLook); snap = false; }
+    _sc.copy(dLook).sub(controls.target).multiplyScalar(1 - Math.exp(-3 * rdt));
+    camera.position.add(_sc); controls.target.add(_sc);
+    controls.update(rdt);
+    camPos.copy(camera.position); camLook.copy(controls.target);
+    return;
+  }
+  if (snap) { camPos.copy(dPos); camLook.copy(dLook); snap = false; }
+  else {
+    camPos.lerp(dPos, 1 - Math.exp(-(camMode === 'follow' ? 5 : 2.6) * rdt));
+    camLook.lerp(dLook, 1 - Math.exp(-4 * rdt));
+  }
+  camera.position.copy(camPos);
+  camera.lookAt(camLook);
+  if (vdt > 0 && S.trauma > 0.001) {
+    const a = S.trauma * S.trauma, tt = S.time * 41;
+    camera.position.x += (Math.sin(tt * 1.3) + Math.sin(tt * 2.9 + 1)) * 0.5 * a * 0.22;
+    camera.position.y += (Math.sin(tt * 1.7 + 2) + Math.sin(tt * 3.3)) * 0.5 * a * 0.18;
+    camera.position.z += (Math.sin(tt * 1.1 + 4) + Math.sin(tt * 2.3 + 3)) * 0.5 * a * 0.22;
+    camera.rotateZ(Math.sin(tt * 1.9) * a * 0.03);
+  }
+}
+
+function setCam(mode) {
+  camMode = mode; snap = true;
+  camera.position.copy(camPos);
+  controls.enabled = mode === 'orbit';
+  if (mode === 'orbit') { camera.up.set(0, 1, 0); controls.autoRotate = true; camera.position.copy(camPos); }
+  document.querySelectorAll('#gCam button').forEach(b => b.classList.toggle('active', b.dataset.cam === mode));
+}
