+/* ------------------------------------------------------------------ */
+/* Start / UI                                                          */
+/* ------------------------------------------------------------------ */
+function startRun(cfg) {
+  applied = { ...cfg };
+  const lay = layout(cfg);
+  const key = cfg.trackLen + '|' + lay.hw.toFixed(3) + '|' + lay.startX.toFixed(3) + '|' + cfg.carL + '|' + cfg.carW;
+  if (key !== trackKey) { buildTrack(cfg, lay); trackKey = key; }
+  dust.reset(); sparks.reset();
+  skid.count = 0; skidN = 0;
+  newRun(cfg);
+  syncScene();
+  updateTopCam();
+  if (camMode === 'orbit') { camLook.set(lay.wallX - 1, 0.9, 0); }
+  snap = true;
+  if (camMode === 'impact' || camMode === 'follow') { updateCameraSnapNow(); }
+  playing = true;
+  updateHudButtons();
+}
+function updateCameraSnapNow() { snap = true; updateCamera(0.016, 0); }
+
+function doApply() { startRun(readSettings()); }
+
+function updateHudButtons() { $('bPlay').textContent = playing ? 'Pause' : 'Play'; }
+function togglePlay() { playing = !playing; updateHudButtons(); }
+
+$('bPlay').addEventListener('click', togglePlay);
+$('bReplay').addEventListener('click', doApply);
+$('bApply').addEventListener('click', doApply);
+$('bDefaults').addEventListener('click', () => { writeSettings(DEF); doApply(); });
+$('bSet').addEventListener('click', () => { $('panel').classList.toggle('open'); $('bSet').classList.toggle('active'); });
+document.querySelectorAll('#gSpeed button').forEach(b => b.addEventListener('click', () => {
+  speedMul = parseFloat(b.dataset.speed);
+  document.querySelectorAll('#gSpeed button').forEach(x => x.classList.toggle('active', x === b));
+}));
+document.querySelectorAll('#gCam button').forEach(b => b.addEventListener('click', () => setCam(b.dataset.cam)));
+window.addEventListener('keydown', e => {
+  if (e.code !== 'Space' && e.key !== ' ') return;
+  const a = document.activeElement;
+  if (a && a.tagName === 'INPUT' && a.type === 'number') return;
+  e.preventDefault();
+  if (!e.repeat) togglePlay();
+});
+
+function resize() {
+  const w = innerWidth, h = innerHeight;
+  renderer.setSize(w, h, false);
+  camera.aspect = w / h; camera.updateProjectionMatrix();
+  topCam.aspect = w / h; topCam.updateProjectionMatrix();
+  updateTopCam();
+}
+window.addEventListener('resize', resize);
+resize();
+
+/* ------------------------------------------------------------------ */
+/* Main loop                                                           */
+/* ------------------------------------------------------------------ */
+let last = performance.now(), hudTick = 0;
+function frame(now) {
+  requestAnimationFrame(frame);
+  const rdt = Math.min(0.05, (now - last) / 1000); last = now;
+  if (!S) return;
+  let vdt = 0;
+  if (playing) {
+    S.acc += rdt * speedMul;
+    let n = 0;
+    while (S.acc >= S.dt && n < 24) { stepSim(); S.acc -= S.dt; n++; }
+    if (S.acc >= S.dt) S.acc = 0;
+    vdt = rdt * speedMul;
+  }
+  syncScene();
+  if (vdt > 0) {
+    dust.update(vdt, 0.25, 1.3);
+    sparks.update(vdt, -9.81, 0.4);
+    S.trauma = Math.max(0, S.trauma - vdt * 1.5);
+  }
+  updateCamera(rdt, vdt);
+  const cam = camMode === 'top' ? topCam : camera;
+  sky.position.copy(cam.position);
+  partUniformScale.value = renderer.domElement.height / (2 * Math.tan(cam.fov * Math.PI / 360));
+  renderer.render(scene, cam);
+  if (++hudTick % 6 === 0) {
+    const v = S.tub.body.velocity.length();
+    const free = S.parts.filter(p => p.detached).length;
+    $('hud').textContent = `t ${S.time.toFixed(2)} s · ${v.toFixed(1)} m/s · ${free}/${S.parts.length} free${S.settled ? ' · settled' : ''}`;
+  }
+}
+
+startRun({ ...DEF });
+requestAnimationFrame(frame);
+</script>
+</body>
+</html>
